usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Admin.Organization.Projects.RateLimits.UpdateRateLimit(
		context.TODO(),
		"project_id",
		"rate_limit_id",
		openai.AdminOrganizationProjectRateLimitUpdateRateLimitParams{
			MaxRequestsPer1Minute: param.NewOpt[int64](1),
			MaxTokensPer1Minute: param.NewOpt[int64](1),
			MaxImagesPer1Minute: param.NewOpt[int64](1),
			MaxAudioMegabytesPer1Minute: param.NewOpt[int64](1),
			MaxRequestsPer1Day: param.NewOpt[int64](1),
			Batch1DayMaxInputTokens: param.NewOpt[int64](1),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
